import{_ as s,C as n,o,c as r,j as t,a as i,E as l,a6 as h}from"./chunks/framework.CCKCzdWs.js";const y=JSON.parse(`{"title":"Page events, text and filmstrip","description":"Under the live view of a running Playwright test: its page's console errors, failed and slow requests and backend errors, its text as roles and names, and a filmstrip of its calls, masked in the worker and never stored.","frontmatter":{"title":"Page events, text and filmstrip","description":"Under the live view of a running Playwright test: its page's console errors, failed and slow requests and backend errors, its text as roles and names, and a filmstrip of its calls, masked in the worker and never stored.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/live-view-layers.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/live-view-layers.html"}],["meta",{"property":"og:title","content":"Page events, text and filmstrip | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Under the live view of a running Playwright test: its page's console errors, failed and slow requests and backend errors, its text as roles and names, and a filmstrip of its calls, masked in the worker and never stored."}]]},"headers":[],"relativePath":"features/live-view-layers.md","filePath":"features/live-view-layers.md","lastUpdated":1795277177000}`),d={name:"features/live-view-layers.md"};function c(g,e,p,w,m,u){const a=n("Needs");return o(),r("div",null,[e[0]||(e[0]=t("h1",{id:"page-events-text-and-filmstrip",tabindex:"-1"},[i("Page events, text and filmstrip "),t("a",{class:"header-anchor",href:"#page-events-text-and-filmstrip","aria-label":'Permalink to "Page events, text and filmstrip"'},"​")],-1)),l(a,{reporter:"",fixtures:""}),e[1]||(e[1]=h('<p>Under the image of a worker&#39;s <a href="./live-view.html">live view</a>, the panel also shows what the image cannot: what the page and the test&#39;s requests said, the page as text, and a filmstrip of the test&#39;s calls. It is for a test that fails or waits for a reason the pixels do not show: a console error, a request that never answered, a 500 and the exception the backend logged for it. Each part comes from the worker only while the panel shows it, in a CI run or a run <a href="./share-live.html">shared from a developer&#39;s machine</a>, and the dashboard stores none of it. Your editor, Piwi Picker&#39;s Runs window and the desktop app show the same beside a test they watch: <a href="#in-your-own-tools">in your own tools</a>.</p><h2 id="page-events" tabindex="-1">Page events <a class="header-anchor" href="#page-events" aria-label="Permalink to &quot;Page events&quot;">​</a></h2><p><strong>Page events</strong>, open by default, lists as they happen, newest first:</p><ul><li><strong>Console errors</strong> and <strong>uncaught errors</strong> the page threw;</li><li><strong>failed requests</strong>: no answer, or a status of 400 or more;</li><li><strong>pending requests</strong>, once one has waited 5 seconds for its answer: one line whose time grows (<code>POST /api/checkout</code>, pending for 17 s), then says how long it took;</li><li>what the backend <strong>logged</strong> while it answered, errors and warnings, under the request it answered, from its <a href="/guide/backend-logs.html">backend instrumentation</a>;</li><li>the test&#39;s <strong>API calls</strong> through Playwright&#39;s <code>request</code>, with their status and time: a test with no page shows these.</li></ul><p>Addresses and texts reach the dashboard with their credentials hidden. A worker sends 20 events a second at most and counts the others, the dashboard counts those a page reading too slowly could not take, and the list keeps the latest 100; each says how many it left out. Folding the section stops them coming.</p><h2 id="page-text" tabindex="-1">Page text <a class="header-anchor" href="#page-text" aria-label="Permalink to &quot;Page text&quot;">​</a></h2><p><strong>Page text</strong>, folded by default, shows the page as roles and names when you open it, as Playwright&#39;s ARIA snapshot writes it (<code>- button &quot;Pay €84.90&quot; [disabled]</code>): what a screen reader would read, searchable and selectable at any width.</p><ul><li><strong>Where it comes from</strong>: the test&#39;s own trace, when the project&#39;s trace takes ARIA snapshots (<code>snapshots.aria</code>; <code>wrapConfig</code>&#39;s does not), a new one after each call. Otherwise the worker reads the page as you open the section or choose <strong>Read again</strong>: about 8 levels deep, which can hold a heavy page&#39;s test up for 120 to 300 milliseconds.</li><li><strong>Find in the text</strong> ignores case and accents, and says how many matches it has.</li><li><strong>The element the call waits on</strong>, when its locator names it by role and name, label, placeholder or text (<code>getByRole(&#39;button&#39;, { name: &#39;Pay&#39; })</code>), is marked in the text.</li><li><strong>Masked in the worker</strong>: the value of a password, PIN, one-time code or card field, anything that reads as a card&#39;s number, the values the page&#39;s secret fields hold, and the project&#39;s <strong>Masked elements</strong> read <code>&lt;hidden&gt;</code>. A masked element the snapshot cannot name sends no text, and the section says why.</li></ul><p>A text is 96 K characters and 192 KB at most, and says so when it is cut.</p><h2 id="filmstrip" tabindex="-1">Filmstrip <a class="header-anchor" href="#filmstrip" aria-label="Permalink to &quot;Filmstrip&quot;">​</a></h2><p>Under the image, the <strong>filmstrip</strong> shows the page after each call of the test that ended, one small image a call; a click on one shows it larger, with its call&#39;s title. The worker takes them from the view&#39;s own images, masked as its frames are, 320 by 200 pixels at most, only while someone watches, and keeps the current test&#39;s strip in its memory, 40 images at most. A view that opens later gets that strip at once: from the test&#39;s start, when someone watched it all along.</p><h2 id="what-is-sent-and-what-is-kept" tabindex="-1">What is sent, and what is kept <a class="header-anchor" href="#what-is-sent-and-what-is-kept" aria-label="Permalink to &quot;What is sent, and what is kept&quot;">​</a></h2><ul><li><strong>Only what a panel shows.</strong> The worker sends events while a panel shows <strong>Page events</strong>, the text as one opens <strong>Page text</strong>, and the filmstrip while a panel shows the worker; to those panels alone.</li><li><strong>Bounded.</strong> The dashboard relays at most 40 events, 4 texts and 16 filmstrip images a second of a worker; the images count against the <a href="./live-view.html#limits">bytes</a> a run&#39;s workers and each page may send, and a page past its bytes gets the filmstrip&#39;s images a little later, in their order.</li><li><strong>Nothing is kept.</strong> As with the images, the dashboard relays each part and drops it: never written to the database, the logs or an export. The panel holds the parts of the test it shows in the browser&#39;s memory, until the view moves to the next test or closes.</li></ul><p>A worker of an older reporter sends none of them: the sections stay empty, and <strong>Page text</strong> says no text came.</p><h2 id="in-your-own-tools" tabindex="-1">In your own tools <a class="header-anchor" href="#in-your-own-tools" aria-label="Permalink to &quot;In your own tools&quot;">​</a></h2><p>Under a watched page in your editor&#39;s view, a CI run&#39;s lane included, and, with a reporter newer than 0.68.0, in Piwi Picker&#39;s Runs window and the desktop app&#39;s tray (<a href="./watch-running-test.html">Watch a local test</a>):</p><ul><li><strong>Why it waits</strong>: the call the test is in, how long it has run, how many elements its locator matches and whether the first is enabled, and the last lines of Playwright&#39;s log.</li><li><strong>Events</strong>: console and uncaught errors, failed requests, requests pending long (<code>POST /api/checkout pending 17 s</code>) and the errors the backend logged, newest first.</li><li><strong>Text</strong>: the page as roles and names, its secret fields hidden, read at each test (<strong>Show the page&#39;s text</strong> in the Runs window and the tray), then followed through the test&#39;s trace. Find searches it.</li><li><strong>Filmstrip</strong>: one image per call the test finished; a click shows it larger, with its call.</li></ul><p>The text and the filmstrip are read only while open, and kept in memory alone, on your machine. The view says when an older reporter, or team instance, may send none of them.</p><h2 id="in-the-demo" tabindex="-1">In the demo <a class="header-anchor" href="#in-the-demo" aria-label="Permalink to &quot;In the demo&quot;">​</a></h2><p>The live demo runs no browser. <strong>Watch</strong> on a simulated run&#39;s running test, or a tile of <a href="./watch-all.html#in-the-demo">Watch all</a>, opens its worker&#39;s panel with no image: the call its test is in, with its log, and <a href="./live-inspect.html#in-the-demo">Inspect</a> on the checkout page from a recorded trace. The page&#39;s events and the filmstrip stay empty; the panel says why no image comes, and <strong>Page text</strong> why no text does.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./live-view.html">Live view of a run</a>: turning it on, and the image and call of one worker</li><li><a href="./watch-all.html">Watch all workers</a>: every worker of a run at once</li><li><a href="./live-inspect.html">Inspect a worker&#39;s page</a>: the page at each call as a document, with the locator picker</li><li><a href="/guide/backend-logs.html">Backend logs</a>: what the backend instrumentation attaches to a response</li><li><a href="./evidence.html">Failure evidence</a>: the console, network and ARIA a finished test keeps</li></ul>',22))])}const k=s(d,[["render",c]]);export{y as __pageData,k as default};
